103|function loadSessions(): Session[] {
104|  const sessions: Session[] = [];
105|  function walk(dir: string) {
106|    if (!existsSync(dir)) return;
107|    const entries = readdirSync(dir, { withFileTypes: true });
108|    for (const entry of entries) {
109|      const full = join(dir, entry.name);
110|      if (entry.isDirectory()) { walk(full); continue; }
111|      if (!entry.name.endsWith(".jsonl")) continue;
112|      const content = readFileSync(full, "utf-8");
113|      const lines = content.split("\n").filter((l: string) => l.trim());
114|      const events: any[] = [];
115|      for (const line of lines) {
116|        try { events.push(JSON.parse(line)); } catch { /* skip */ }
117|      }
118|      const types = new Map<string, number>();
119|      for (const e of events) {
120|        const t = e.type || "?";
121|        types.set(t, (types.get(t) || 0) + 1);
122|      }
123|      const title = extractTitle(events);
124|      const model = extractModel(events);
125|      const cwd = extractCwd(events);
126|      const intent = inferIntent(title, model, cwd);
127|      const completed = inferCompleted(types, events);
128|      const anomalyScore = computeAnomalyScore({ events, types, file: full, intent, completed, model, cwd, title, sessionId: "" });
129|      sessions.push({ file: full.replace(SESSIONS_DIR, "").replace(/^\//, ""), events: events.length, types, title, model, cwd, intent, completed, anomalyScore });
130|    }
131|  }
132|  walk(SESSIONS_DIR);
133|  return sessions.sort((a, b) => b.events - a.events);
