138|// K-means clustering
139|function clusterSessions(sessions: Session[], k: number = 3): Map<number, Session[]> {
140|  const features = sessions.map((s) => s.events);
141|  const min = Math.min(...features);
142|  const range = Math.max(...features) - min || 1;
143|  const centroids: number[] = [];
144|  for (let i = 0; i < k; i++) centroids.push(min + (range * i) / (k - 1));
145|  let clusters: Map<number, Session[]> = new Map();
146|  for (let iter = 0; iter < 20; iter++) {
147|    clusters = new Map();
148|    for (let i = 0; i < k; i++) clusters.set(i, []);
149|    for (const s of sessions) {
150|      let nearest = 0, minDist = Math.abs(s.events - centroids[0]);
151|      for (let c = 1; c < k; c++) { const d = Math.abs(s.events - centroids[c]); if (d < minDist) { minDist = d; nearest = c; } }
152|      clusters.get(nearest)!.push(s);
153|    }
154|    for (let c = 0; c < k; c++) { const cl = clusters.get(c)!; if (cl.length > 0) centroids[c] = cl.reduce((sum: number, s: Session) => sum + s.events, 0) / cl.length; }
155|  }
156|  return clusters;
