import json
from pathlib import Path

def deep_audit_session(path_str):
    p = Path(path_str)
    events = []
    with open(p, "r", encoding="utf-8", errors="ignore") as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    events.append(json.loads(line))
                except Exception:
                    pass

    current_model = "unknown"
    model_actions = {} # model -> list of {user_prompt, assistant_replies, tool_calls, tool_errors, claimed_completions}

    current_user_prompt = ""
    last_assistant_text = ""

    for e in events:
        t = e.get("type")
        if t == "model_change":
            current_model = e.get("model") or current_model
            if current_model not in model_actions:
                model_actions[current_model] = {
                    "tool_calls": [],
                    "tool_errors": [],
                    "assistant_texts": [],
                    "user_prompts": []
                }
        elif t == "custom" and e.get("customType") == "tool_execution_start":
            data = e.get("data", {})
            t_name = data.get("toolName")
            t_args = data.get("args")
            if current_model not in model_actions:
                model_actions[current_model] = {"tool_calls": [], "tool_errors": [], "assistant_texts": [], "user_prompts": []}
            model_actions[current_model]["tool_calls"].append({
                "tool": t_name,
                "args": str(t_args)[:150]
            })
        elif t == "message":
            msg = e.get("message", {})
            role = msg.get("role")
            content = msg.get("content", [])
            if role == "user":
                txt = ""
                if isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict) and c.get("type") == "text":
                            txt += c.get("text", "")
                        elif isinstance(c, str):
                            txt += c
                elif isinstance(content, str):
                    txt = content
                current_user_prompt = txt
                if current_model in model_actions:
                    model_actions[current_model]["user_prompts"].append(txt[:200])
            elif role == "assistant":
                txt = ""
                if isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict) and c.get("type") == "text":
                            txt += c.get("text", "")
                elif isinstance(content, str):
                    txt = content
                if txt.strip():
                    if current_model not in model_actions:
                        model_actions[current_model] = {"tool_calls": [], "tool_errors": [], "assistant_texts": [], "user_prompts": []}
                    model_actions[current_model]["assistant_texts"].append(txt)
            elif role == "toolResult":
                is_err = msg.get("isError", False)
                res_content = msg.get("content", "")
                if is_err:
                    if current_model not in model_actions:
                        model_actions[current_model] = {"tool_calls": [], "tool_errors": [], "assistant_texts": [], "user_prompts": []}
                    model_actions[current_model]["tool_errors"].append(str(res_content)[:200])

    return {
        "file": p.name,
        "models": model_actions
    }

