        cid = d.get("toolCallId")
        tname = d.get("toolName")
        args = d.get("args")
        pending_calls[cid] = {"tool": tname, "args": args}
    elif t == "message":
        msg = e.get("message", {})
        if msg.get("role") == "toolResult":
            cid = msg.get("toolCallId")
            call_info = pending_calls.pop(cid, {"tool": "unknown", "args": {}})
            content = msg.get("content", "")
            is_err = msg.get("isError", False)
            tool_history.append({
                "tool": call_info["tool"],
                "args": call_info["args"],
                "is_error": is_err,
                "result_snippet": str(content)[:250]
            })

print(f"\nTotal tool executions traced: {len(tool_history)}")

# Look at bash commands, test runs, build runs
for i, th in enumerate(tool_history):
    tool = th["tool"]
    args = th["args"]
    if tool in ["bash", "eval", "edit", "apply_patch", "write"]:
        cmd_or_path = args.get("command") or args.get("path") or str(args)[:80]
        err_flag = " [ERROR]" if th["is_error"] else ""
        if "test" in str(cmd_or_path).lower() or "build" in str(cmd_or_path).lower() or "bun" in str(cmd_or_path).lower() or th["is_error"]:
            print(f"#{i} {tool} ({cmd_or_path}){err_flag}:")
            print(f"   result: {th['result_snippet'].replace(chr(10), ' ')[:160]}")

