import json
import glob
import re
from pathlib import Path
from collections import defaultdict

session_files = glob.glob("/home/toxic/.tau/agent/sessions/**/*.jsonl", recursive=True)

patterns = {
    "tool_error_then_claim_success": [],
    "rule_violation_triggers": [],
    "model_churn_sessions": [],
    "pseudo_syntax_leaks": [],
    "repeated_command_loops": [],
    "subagent_empty_yields": [],
    "unverified_test_pass_claims": [],
    "escape_hatch_stubs": [],
    "fork_brand_confusion": []
}

for sfile in session_files:
    fname = Path(sfile).name
    events = []
    with open(sfile, "r", encoding="utf-8", errors="ignore") as f:
        for line in f:
            if line.strip():
                try:
                    events.append(json.loads(line))
                except:
                    pass

    models_used = set()
    tool_history = [] # (index, name, args, is_error, output)
    rule_violations = []

    for i, e in enumerate(events):
        t = e.get("type")
        if t == "model_change":
            if e.get("model"): models_used.add(e.get("model"))
        elif t == "message":
            msg = e.get("message", {})
            role = msg.get("role")
            content = msg.get("content")

            # Check tool results
            if role == "toolResult":
                c_str = str(content)
                is_err = msg.get("isError", False) or "error TS" in c_str or "Command exited with code" in c_str or "Error:" in c_str
                if "rule_violation" in c_str:
                    m = re.search(r'rule="([^"]+)"', c_str)
                    rule_violations.append(m.group(1) if m else "unknown_rule")
                tool_history.append((i, msg.get("toolName"), is_err, c_str[:200]))

            elif role == "assistant":
                text = ""
                thinking = ""
                if isinstance(content, list):
                    for part in content:
                        if isinstance(part, dict):
                            if part.get("type") == "text": text += part.get("text", "")
                            elif part.get("type") == "thinking": thinking += part.get("thinking", "")
                elif isinstance(content, str):
                    text = content

                # Check pseudo syntax leaks
                if any(k in text for k in ["SM:FIND", "SM:EDIT", "SM:AFTER", "<system-action>", "</thinking>", "<toolcall>"]):
                    patterns["pseudo_syntax_leaks"].append({
                        "file": fname,
                        "event": i,
                        "leak": [k for k in ["SM:FIND", "SM:EDIT", "SM:AFTER", "<system-action>", "</thinking>", "<toolcall>"] if k in text],
                        "snippet": text[:150]
                    })

                # Check for claims of success right after errors
                if ("all tests pass" in text.lower() or "successfully implemented" in text.lower() or "all tasks completed" in text.lower()):
                    if tool_history and tool_history[-1][2]: # last tool was error
                        patterns["tool_error_then_claim_success"].append({
                            "file": fname,
                            "event": i,
                            "last_tool": tool_history[-1][1],
                            "error": tool_history[-1][3][:120],
                            "claim": text[:150]
                        })

                # Check for fake test passes
                if "test" in text.lower() and ("pass" in text.lower() or "100%" in text.lower() or "verified" in text.lower()):
                    # Did we run any test tool recently?
                    recent_tools = [th[1] for th in tool_history[-5:]]
                    if not any(t in ["bash", "eval"] for t in recent_tools):
                        patterns["unverified_test_pass_claims"].append({
                            "file": fname,
                            "event": i,
                            "claim": text[:120]
                        })

                # Check for escape hatch stubs
                if "escape hatch" in text.lower() and "/tmp" in text.lower():
                    patterns["escape_hatch_stubs"].append({
                        "file": fname,
                        "snippet": text[:150]
                    })

    # Check model churn
    if len(models_used) >= 4:
        patterns["model_churn_sessions"].append({
            "file": fname,
            "models_count": len(models_used),
            "models": list(models_used)
        })

    # Check rule violations
    if len(rule_violations) >= 2:
        patterns["rule_violation_triggers"].append({
            "file": fname,
            "violations_count": len(rule_violations),
            "rules": list(set(rule_violations))
        })

    # Check repeated command loops
    bash_cmds = []
    for th in tool_history:
        # Check repeated errors
        if th[2]:
            bash_cmds.append(th[3][:60])
    for cmd, cnt in defaultdict(int, {c: bash_cmds.count(c) for c in bash_cmds}).items():
        if cnt >= 4:
            patterns["repeated_command_loops"].append({
                "file": fname,
                "count": cnt,
                "error_snippet": cmd
            })

print("SUMMARY OF DISCOVERED PATTERNS ACROSS ALL SESSIONS:")
print("="*70)
for pat_name, items in patterns.items():
    print(f"• {pat_name}: {len(items)} instances found")

