import { readFile } from "fs/promises";
import * as path from "path";

/**
 * Loaded capability manifest.
 */
let manifest: CapabilityManifest | null = null;

/**
 * Load the manifest from disk. Should be called once at startup.
 */
export async function loadManifest(manifestPath: string): Promise<void> {
  const content = await readFile(manifestPath, "utf-8");
  manifest = JSON.parse(content) as CapabilityManifest;
}

/**
 * Resolve a capability name to its provider path.
 * Returns null if not found.
 */
export function resolveCapability(name: string): string | null {
  if (!manifest) {
    throw new Error("Manifest not loaded. Call loadManifest first.");
  }
  const entry = manifest.entries.find(e => e.name === name);
  return entry ? entry.provider : null;
}

/**
 * Get all capability entries.
 */
export function getAllCapabilities(): CapabilityEntry[] {
  if (!manifest) {
    throw new Error("Manifest not loaded. Call loadManifest first.");
  }
  return [...manifest.entries];
}

/**
 * Get synthesis hint for a capability if present.
 */
export function getSynthesisHint(name: string): string | undefined {
  if (!manifest) {
    throw new Error("Manifest not loaded. Call loadManifest first.");
  }
  const entry = manifest.entries.find(e => e.name === name);
  return entry?.synthesize;
}

interface CapabilityEntry {
  name: string;
  kind: "export" | "hook" | "tool" | "provider" | "config";
  provider: string;
  aliases?: string[];
  synthesize?: string;
}

interface CapabilityManifest {
  schemaVersion: string;
  generatedAt: string;
  entries: CapabilityEntry[];
}
