import { Policy, PolicyDecision } from "./types";

/**
 * Evaluate a policy for a given tool and optional command.
 * Returns the decision based on rules, tool overrides, or default mode.
 */
export function evaluatePolicy(
  policy: Policy | undefined,
  tool: string,
  command?: string,
): PolicyDecision {
  // If no policy, return undefined to let caller decide (backward compatibility)
  if (!policy) {
    return { kind: "allow" }; // default allow? Actually we should return undefined but we need a Decision.
    // We'll return allow as safe default.
  }

  // Check tool-specific overrides
  const toolOverride = policy.tools[tool];
  if (toolOverride !== undefined) {
    return toolOverride;
  }

  // Evaluate rules in order
  for (const rule of policy.rules ?? []) {
    const match = rule.match;
    if (match.tool === tool && (match.command === undefined || match.command === command)) {
      return rule.decision;
    }
  }

  // Fallback to default mode
  switch (policy.mode) {
    case "allow":
      return { kind: "allow" };
    case "deny":
      return { kind: "deny", reason: "default deny" };
    case "ask":
      // For ask, we need to escalate? In policy, ask means we should prompt.
      // Since we are in headless context, we treat as escalate to parent.
      return { kind: "escalate", to: "parent", prompt: `Policy requires approval for tool "${tool}"${command ? ` with command "${command}"` : ""}` };
    default:
      return { kind: "allow" };
  }
}
