import os
import subprocess
from pathlib import Path

target_dirs = [
    Path("/home/toxic/projects/dedi-ops"),
    Path("/home/toxic/projects/websites/dedi-ops"),
    Path("/home/toxic/session-burn-radar/worktrees/dedi-ops"),
    Path("/home/toxic/workspace/worktrees/dedi-ops"),
    Path("/home/toxic/staging-20260914/preserve/archive-clone/worktrees/dedi-ops"),
]

for d in target_dirs:
    print("="*70)
    print(f"DIRECTORY: {d} (exists={d.exists()})")
    if not d.exists():
        continue

    # Check if git repo or worktree
    git_dir = d / ".git"
    if git_dir.exists():
        if git_dir.is_file():
            print(f"  .git file (worktree ref): {git_dir.read_text().strip()}")
        else:
            print("  .git directory (main repo)")
        try:
            remotes = subprocess.run(["git", "-C", str(d), "remote", "-v"], capture_output=True, text=True).stdout.strip()
            print(f"  Remotes:\n    {remotes.replace(chr(10), chr(10)+'    ')}")
            branch = subprocess.run(["git", "-C", str(d), "branch", "--show-current"], capture_output=True, text=True).stdout.strip()
            print(f"  Branch: {branch}")
            status = subprocess.run(["git", "-C", str(d), "status", "--short"], capture_output=True, text=True).stdout.strip()
            if status:
                print(f"  Status (short):\n    {status.replace(chr(10), chr(10)+'    ')}")
            else:
                print("  Status: clean")
        except Exception as e:
            print(f"  Git error: {e}")
    else:
        print("  Not a direct git root")

    # List files
    files = []
    for root, dirs, fnames in os.walk(d):
        if ".git" in root or "__pycache__" in root or "node_modules" in root:
            continue
        rel_root = Path(root).relative_to(d)
        for fn in fnames:
            fp = Path(root) / fn
            files.append((str(rel_root / fn) if str(rel_root) != "." else fn, fp.stat().st_size))

    print(f"  Files ({len(files)}):")
    for fpath, sz in sorted(files)[:20]:
        print(f"    - {fpath} ({sz} bytes)")
    if len(files) > 20:
        print(f"    ... and {len(files) - 20} more files")

