import hashlib
from pathlib import Path

def parse_env_hashes(p):
    hashes = {}
    with open(p) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                h = hashlib.sha256(v.encode()).hexdigest()[:8]
                hashes[k.strip()] = (len(v), h)
    return hashes

h1 = parse_env_hashes(Path("/home/toxic/projects/dedi-ops/.env"))
h2 = parse_env_hashes(Path("/home/toxic/projects/websites/dedi-ops/.env"))

differences = []
for k in h1:
    if h1[k] != h2.get(k):
        differences.append((k, h1[k], h2.get(k)))

print(f"Differences between /home/toxic/projects/dedi-ops/.env and /home/toxic/projects/websites/dedi-ops/.env: {len(differences)}")
for k, v1, v2 in differences:
    print(f"  {k}: dedi-ops len={v1[0]} (hash={v1[1]}) vs websites len={v2[0]} (hash={v2[1]})")

