import os
import filecmp
from pathlib import Path

p_main = Path("/home/toxic/projects/dedi-ops")
p_web = Path("/home/toxic/projects/websites/dedi-ops")

web_files = []
for root, dirs, fnames in os.walk(p_web):
    if ".git" in root or "__pycache__" in root or "node_modules" in root:
        continue
    rel = Path(root).relative_to(p_web)
    for fn in fnames:
        web_files.append(rel / fn if str(rel) != "." else Path(fn))

print(f"Total files in websites/dedi-ops: {len(web_files)}")
print("\nComparison against projects/dedi-ops:")
for wf in sorted(web_files):
    target = p_main / wf
    if not target.exists():
        print(f"  [ONLY IN WEBSITES] {wf}")
    else:
        # compare
        same = filecmp.cmp(p_web / wf, target, shallow=False)
        if same:
            print(f"  [IDENTICAL] {wf}")
        else:
            print(f"  [DIFFERENT] {wf} (web sz={ (p_web / wf).stat().st_size }, main sz={ target.stat().st_size })")

