{
  "name": "@sovereign/utils",
  "version": "0.1.0",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "build": "tsc",
    "test": "bun test"
  },
  "dependencies": {}
}

export interface CapabilityEntry {
  name: string;
  kind: "export" | "hook" | "tool" | "provider" | "config";
  provider: string;
  aliases?: string[];
  synthesize?: string;
}

export interface CapabilityManifest {
  schemaVersion: string;
  generatedAt: string;
  entries: CapabilityEntry[];
}

import { readFile } from "node:fs/promises";
import type { CapabilityEntry, CapabilityManifest } from "./manifest";

let activeManifest: CapabilityManifest | null = null;

export async function loadManifest(manifestPath: string): Promise<CapabilityManifest> {
  const content = await readFile(manifestPath, "utf-8");
  activeManifest = JSON.parse(content) as CapabilityManifest;
  return activeManifest;
}

export function setManifest(manifest: CapabilityManifest): void {
  activeManifest = manifest;
}

export function resolveCapability(name: string): string | null {
  if (!activeManifest) {
    throw new Error("Manifest not loaded. Call loadManifest or setManifest first.");
  }
  const entry = activeManifest.entries.find((e) => e.name === name || e.aliases?.includes(name));
  return entry ? entry.provider : null;
}

export function getAllCapabilities(): CapabilityEntry[] {
  if (!activeManifest) {
    throw new Error("Manifest not loaded. Call loadManifest or setManifest first.");
  }
  return [...activeManifest.entries];
}

export function getSynthesisHint(name: string): string | undefined {
  if (!activeManifest) {
    throw new Error("Manifest not loaded. Call loadManifest or setManifest first.");
  }
  const entry = activeManifest.entries.find((e) => e.name === name || e.aliases?.includes(name));
  return entry?.synthesize;
}

export type PolicyDecision =
  | { kind: "allow" }
  | { kind: "deny"; reason: string }
  | { kind: "escalate"; to: "parent" | "user"; prompt: string };

export interface PolicyRule {
  match: { tool: string; command?: string };
  decision: PolicyDecision;
}

export interface Policy {
  schemaVersion: string;
  mode: "allow" | "deny" | "ask";
  tools: Record<string, PolicyDecision>;
  inheritFromParent: boolean;
  rules?: PolicyRule[];
}

import type { Policy, PolicyDecision } from "./types";

export function evaluatePolicy(
  policy: Policy | undefined,
  tool: string,
  command?: string,
): PolicyDecision {
  if (!policy) {
    return { kind: "allow" };
  }

  const toolOverride = policy.tools[tool];
  if (toolOverride !== undefined) {
    return toolOverride;
  }

  for (const rule of policy.rules ?? []) {
    const match = rule.match;
    if (match.tool === tool && (match.command === undefined || match.command === command)) {
      return rule.decision;
    }
  }

  switch (policy.mode) {
    case "allow":
      return { kind: "allow" };
    case "deny":
      return { kind: "deny", reason: "default deny by policy mode" };
    case "ask":
      return {
        kind: "escalate",
        to: "parent",
        prompt: `Policy requires approval for tool "${tool}"${command ? ` with command "${command}"` : ""}`,
      };
    default:
      return { kind: "allow" };
  }
}

// @sovereign/utils — Core capabilities and policy channel
export * from "./capabilities/index";
export * from "./policy/index";

import { describe, it, expect } from "bun:test";
import { setManifest, resolveCapability, getAllCapabilities, getSynthesisHint } from "../src/capabilities/index";
import { evaluatePolicy } from "../src/policy/index";
import type { CapabilityManifest } from "../src/capabilities/manifest";
import type { Policy } from "../src/policy/types";

describe("@sovereign/utils", () => {
  describe("capabilities", () => {
    const testManifest: CapabilityManifest = {
      schemaVersion: "1.0",
      generatedAt: new Date().toISOString(),
      entries: [
        {
          name: "@oh-my-pi/pi-coding-agent#keyText",
          kind: "export",
          provider: "src/extensibility/shim.ts",
          aliases: ["@mariozechner/pi-coding-agent#keyText"],
          synthesize: "export function keyText() { return ''; }",
        },
      ],
    };

    it("resolves primary capability name", () => {
      setManifest(testManifest);
      expect(resolveCapability("@oh-my-pi/pi-coding-agent#keyText")).toBe("src/extensibility/shim.ts");
    });

    it("resolves alias", () => {
      setManifest(testManifest);
      expect(resolveCapability("@mariozechner/pi-coding-agent#keyText")).toBe("src/extensibility/shim.ts");
    });

    it("returns null for unknown capability", () => {
      setManifest(testManifest);
      expect(resolveCapability("@unknown/capability")).toBeNull();
    });

    it("returns synthesis hint", () => {
      setManifest(testManifest);
      expect(getSynthesisHint("@oh-my-pi/pi-coding-agent#keyText")).toContain("keyText");
    });

    it("returns all capabilities", () => {
      setManifest(testManifest);
      expect(getAllCapabilities().length).toBe(1);
    });
  });

  describe("policy channel", () => {
    const testPolicy: Policy = {
      schemaVersion: "1.0",
      mode: "deny",
      inheritFromParent: true,
      tools: {
        read: { kind: "allow" },
        destructive_tool: { kind: "deny", reason: "strictly blocked" },
      },
      rules: [
        {
          match: { tool: "bash", command: "rm -rf /" },
          decision: { kind: "deny", reason: "catastrophic command" },
        },
        {
          match: { tool: "bash" },
          decision: { kind: "escalate", to: "parent", prompt: "Approve bash" },
        },
      ],
    };

    it("respects tool override allow", () => {
      expect(evaluatePolicy(testPolicy, "read")).toEqual({ kind: "allow" });
    });

    it("respects tool override deny", () => {
      expect(evaluatePolicy(testPolicy, "destructive_tool")).toEqual({
        kind: "deny",
        reason: "strictly blocked",
      });
    });

    it("matches specific command rule before general rule", () => {
      expect(evaluatePolicy(testPolicy, "bash", "rm -rf /")).toEqual({
        kind: "deny",
        reason: "catastrophic command",
      });
    });

    it("falls back to default mode when no tool or rule matches", () => {
      expect(evaluatePolicy(testPolicy, "unspecified_tool")).toEqual({
        kind: "deny",
        reason: "default deny by policy mode",
      });
    });
  });
});

