def _find_repo_mapping(repo_name: str) -> Optional[Dict[str, Any]]:
    payload = _load_repo_target_map()
    repos = payload.get("repos") if isinstance(payload, dict) else []
    if not isinstance(repos, list):
        return None
    for entry in repos:
        if not isinstance(entry, dict):
            continue
        if entry.get("repo") == repo_name:
            return entry
    return None


def _verify_webhook_signature(signature: str, timestamp: str, raw_body: bytes) -> bool:
    if not DEPLOY_WEBHOOK_SECRET:
        return False
    if not signature or not timestamp:
        return False
    try:
        ts_num = int(timestamp)
    except ValueError:
        return False
    if abs(int(time.time()) - ts_num) > DEPLOY_WEBHOOK_TTL_SECONDS:
        return False
    digest = hmac.new(
        DEPLOY_WEBHOOK_SECRET.encode("utf-8"),
        f"{timestamp}.{raw_body.decode('utf-8')}".encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    expected = f"sha256={digest}"
    return hmac.compare_digest(expected, signature.strip())


