@app.post("/temporal/snapshot", tags=["Killer"])
async def create_ghost_snapshot(req: GhostSnapshotRequest, _auth: bool = Depends(require_ops_auth)):
    """Creates a hash-indexed snapshot of a file for rollback."""
    file_path = Path(req.file_path)

    if not file_path.exists():
        raise HTTPException(status_code=404, detail="File not found")

    content = file_path.read_text()
    file_hash = hashlib.sha256(content.encode()).hexdigest()[:12]  # type: ignore

    if req.file_path not in GHOST_INDEX:
        GHOST_INDEX[req.file_path] = {}

    GHOST_INDEX[req.file_path][file_hash] = {
        "timestamp": time.time(),
        "size": len(content),
        "content": content,
        "reason": req.reason
    }

    # Persist to disk
    ghost_file = GHOST_STATE_DIR / f"{file_path.name}_{file_hash}.ghost"
    ghost_file.write_text(content)

    llm_log("GHOST_SNAPSHOT", {
        "file": req.file_path,
        "hash": file_hash,
        "size": len(content),
        "ghost_path": str(ghost_file)
    })

    return {
        "status": "SNAPSHOT_CREATED",
        "file": req.file_path,
        "hash": file_hash,
        "ghost_path": str(ghost_file),
        "total_snapshots": len(GHOST_INDEX[req.file_path])
    }

