def _valid_basic(auth_header: str) -> bool:
    if not (AUTH_USERNAME and AUTH_PASSWORD):
        return False
    if not auth_header.lower().startswith("basic "):
        return False
    encoded = auth_header.split(" ", 1)[1].strip()
    try:
        decoded = base64.b64decode(encoded).decode("utf-8")
    except Exception:
        return False
    if ":" not in decoded:
        return False
    user, password = decoded.split(":", 1)
    return secrets.compare_digest(user, AUTH_USERNAME) and secrets.compare_digest(password, AUTH_PASSWORD)


def _valid_bearer(auth_header: str) -> bool:
    if not auth_header.lower().startswith("bearer "):
        return False
    token = auth_header.split(" ", 1)[1].strip()
    return bool(AUTH_TOKEN) and secrets.compare_digest(token, AUTH_TOKEN)


async def require_ops_auth(request: Request) -> bool:
    auth_header = request.headers.get("authorization", "").strip()
    configured = any((AUTH_TOKEN, AUTH_USERNAME and AUTH_PASSWORD))
    if not configured:
        raise HTTPException(status_code=503, detail="Agent auth is not configured")
    if _valid_bearer(auth_header) or _valid_basic(auth_header):
        return True
    raise HTTPException(
        status_code=401,
        detail="Unauthorized",
        headers={"WWW-Authenticate": "Bearer, Basic realm=\"dedi-ops\""},
    )

