def _read_audit(limit: int = 100) -> List[Dict[str, Any]]:
    if not OPS_AUDIT_LOG.exists():
        return []
    lines = OPS_AUDIT_LOG.read_text(encoding="utf-8").splitlines()
    tail = lines[-limit:]  # type: ignore
    out: List[Dict[str, Any]] = []
    for line in tail:
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    return out


