def _load_repo_target_map() -> Dict[str, Any]:
    if not WEBHOOK_REPO_MAP_PATH.exists():
        return {"repos": []}
    try:
        return json.loads(WEBHOOK_REPO_MAP_PATH.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
