def _extract_image_env_from_compose_service(service_name: str) -> Optional[str]:
    compose_file = Path("/docker-compose.modern.yml") if Path("/docker-compose.modern.yml").exists() else Path("docker-compose.modern.yml")
    if not compose_file.exists():
        return None
    try:
        import yaml  # local import to keep startup light
        data = yaml.safe_load(compose_file.read_text(encoding="utf-8")) or {}
    except Exception:
        return None
    services = data.get("services", {}) if isinstance(data, dict) else {}
    spec = services.get(service_name)
    if not isinstance(spec, dict):
        return None
    image = str(spec.get("image") or "")
    # Example: ${EFFUSION_TICKETS_IMAGE:-ghcr.io/...}
    match = re.search(r"\$\{([A-Z0-9_]+):-[^}]+\}", image)
    if match:
        return match.group(1)
    return None


def _resolve_image_reference(image_expr: Optional[str], env: Dict[str, str]) -> Optional[str]:
    if not image_expr:
        return None
    image_expr = str(image_expr).strip()
    pattern = re.match(r"^\$\{([A-Z0-9_]+):-([^}]+)\}$", image_expr)
    if not pattern:
        return image_expr
    env_key, fallback = pattern.groups()
    return env.get(env_key) or fallback


def _run_service_deploy(target_name: str, args: Dict[str, Any]) -> Dict[str, Any]:
    target = _target_from_registry(target_name)
    if target.get("deployClass") == "infra" and not (ALLOW_INFRA_DEPLOY or bool(args.get("allowInfraDeploy"))):
        return {
            "command": [],
            "exit_code": 1,
            "stdout": "",
            "stderr": f"Target '{target_name}' blocked: infra deploys require DEDI_ALLOW_INFRA_DEPLOY=1",
        }

    service = str(args.get("service") or target.get("service") or "")
    if not service:
        return {"command": [], "exit_code": 1, "stdout": "", "stderr": f"Target '{target_name}' missing service mapping"}

    run_env = os.environ.copy()
    run_env["COMPOSE_IGNORE_ORPHANS"] = "1"
    image_tag = args.get("imageTag") or args.get("image")
    resolved_image = image_tag or _resolve_image_reference(target.get("image"), run_env)

    if resolved_image and str(resolved_image).startswith("ghcr.io/"):
        gh_user = os.getenv("GHCR_USERNAME")
        gh_token = os.getenv("GHCR_PULL_TOKEN")
        if gh_user and gh_token:
            login_proc = subprocess.run(
                ["docker", "login", "ghcr.io", "-u", gh_user, "--password-stdin"],
                input=gh_token,
                capture_output=True,
                text=True,
                timeout=30,
            )
            if login_proc.returncode != 0:
                return {
                    "command": ["docker", "login", "ghcr.io", "-u", gh_user, "--password-stdin"],
                    "exit_code": login_proc.returncode,
                    "stdout": login_proc.stdout[-4000:],  # type: ignore
                    "stderr": login_proc.stderr[-4000:],  # type: ignore
                }
        else:
            return {
                "command": ["docker", "login", "ghcr.io", "-u", "<missing>", "--password-stdin"],
                "exit_code": 1,
                "stdout": "",
                "stderr": "Missing GHCR_USERNAME or GHCR_PULL_TOKEN on agent runtime",
            }

    if resolved_image:
        pull_proc = subprocess.run(["docker", "pull", str(resolved_image)], capture_output=True, text=True, timeout=300)
        if pull_proc.returncode != 0:
            return {
                "command": ["docker", "pull", str(resolved_image)],
                "exit_code": pull_proc.returncode,
                "stdout": pull_proc.stdout[-4000:],  # type: ignore
                "stderr": pull_proc.stderr[-4000:],  # type: ignore
            }

    image_env = target.get("imageEnv") or _extract_image_env_from_compose_service(service)
    if resolved_image and image_env:
        run_env[str(image_env)] = str(resolved_image)

    container_name = target.get("containerName")
    if container_name:
        subprocess.run(["docker", "rm", "-f", str(container_name)], capture_output=True, text=True, timeout=20)

    compose_file = os.getenv("DEDI_COMPOSE_FILE") or ("/docker-compose.modern.yml" if Path("/docker-compose.modern.yml").exists() else "docker-compose.modern.yml")
    compose_project = os.getenv("DEDI_COMPOSE_PROJECT", "dedi-ops")
    project_dir = os.getenv("DEDI_COMPOSE_PROJECT_DIR", "/root/dedi-ops")
    cmd = ["docker", "compose", "-p", compose_project, "--project-directory", project_dir]
    if Path("/.env").exists():
        cmd += ["--env-file", "/.env"]
    pull_policy = str(target.get("pullPolicy") or args.get("pullPolicy") or "missing")
    cmd += ["-f", compose_file, "up", "-d", "--no-deps", "--pull", pull_policy, service]

    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=180, env=run_env)
    result = {
        "target": target_name,
        "service": service,
        "command": cmd,
        "exit_code": proc.returncode,
        "stdout": proc.stdout[-12000:],  # type: ignore
        "stderr": proc.stderr[-12000:],  # type: ignore
    }
    if result["exit_code"] != 0:
        return result

    checks: List[str] = [str(v) for v in target.get("healthChecks") or [] if v]
    if container_name:
        for _ in range(30):
            state = subprocess.run(
                ["docker", "inspect", "-f", "{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}", str(container_name)],
                capture_output=True,
                text=True,
                timeout=10,
            )
            status_line = (state.stdout or "").strip()
            if status_line.startswith("running|healthy") or status_line == "running|":
                break
            time.sleep(2)
        else:
            result["exit_code"] = 1
            result["stderr"] = (result["stderr"] + "\ncontainer did not become healthy in time").strip()
            return result

    for check in checks:
        if check.startswith("file:"):
            file_ref = check.split(":", 1)[1]
            file_path = Path(file_ref)
            if not file_path.is_absolute():
                file_path = Path(__file__).resolve().parent.parent / file_ref
            if not file_path.exists():
                result["exit_code"] = 1
                result["stderr"] = (result["stderr"] + f"\nmissing healthcheck artifact: {file_path}").strip()
                return result
            continue
        curl_proc = subprocess.run(["curl", "-kfsS", check], capture_output=True, text=True, timeout=20)
        if curl_proc.returncode != 0:
            result["exit_code"] = 1
            result["stderr"] = (
                result["stderr"] + f"\nhealthcheck failed for {check}: {curl_proc.stderr[-500:] or curl_proc.stdout[-500:]}"  # type: ignore
            ).strip()
            return result

    return result


async def _post_deploy_callback(url: str, payload: Dict[str, Any], target: Dict[str, Any]):
    callback_secret_env = target.get("callbackSecretEnv")
    headers: Dict[str, str] = {"Content-Type": "application/json"}
    if callback_secret_env:
        callback_secret = os.getenv(str(callback_secret_env), "")
        if callback_secret:
            headers["Authorization"] = f"Bearer {callback_secret}"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            res = await client.post(url, headers=headers, json=payload)
        _append_audit(
            {
                "actor": "system",
                "type": "deploy_callback",
                "target": target.get("target"),
                "url": url,
                "status": res.status_code,
            }
        )
    except Exception as exc:
        _append_audit(
            {
                "actor": "system",
                "type": "deploy_callback_error",
                "target": target.get("target"),
                "url": url,
                "error": str(exc),
            }
        )


def _run_intent_command(command_class: str, args: Dict[str, Any]) -> Dict[str, Any]:
    run_env: Optional[Dict[str, str]] = None
    if command_class == "docker_service_restart":
        svc = args.get("service")
        if not svc:
            raise HTTPException(status_code=400, detail="arguments.service is required")
        cmd = ["docker", "restart", str(svc)]
    elif command_class == "docker_ps":
        cmd = ["docker", "ps", "--format", "json"]
    elif command_class == "logs_capture":
        svc = args.get("service")
        if not svc:
            raise HTTPException(status_code=400, detail="arguments.service is required")
        tail = str(args.get("tail", 200))
        cmd = ["docker", "logs", "--tail", tail, str(svc)]
    elif command_class == "route_reload":
        cmd = ["docker", "restart", "traefik"]
    elif command_class == "health_probe":
        url = args.get("url")
        if not url:
            raise HTTPException(status_code=400, detail="arguments.url is required")
        cmd = ["curl", "-fsS", str(url)]
    elif command_class == "stack_apply":
        services = args.get("services") or []
        run_env = os.environ.copy()
        run_env["COMPOSE_IGNORE_ORPHANS"] = "1"
        if isinstance(services, list) and services:
            cmd = ["docker", "compose", "-f", "docker-compose.modern.yml", "up", "-d", *[str(s) for s in services]]
        else:
            cmd = ["docker", "compose", "-f", "docker-compose.modern.yml", "up", "-d"]
    elif command_class == "tickets_deploy":
        return _run_service_deploy("tickets", args)
    elif command_class == "service_deploy":
        target = str(args.get("target") or "")
        if not target:
            raise HTTPException(status_code=400, detail="arguments.target is required")
        return _run_service_deploy(target, args)
    else:
        raise HTTPException(status_code=400, detail=f"Unsupported commandClass: {command_class}")

    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120, env=run_env)
    result = {
        "command": cmd,
        "exit_code": proc.returncode,
        "stdout": proc.stdout[-12000:],  # type: ignore
        "stderr": proc.stderr[-12000:],  # type: ignore
    }
    return result


