async def ops_intent_execute(req: IntentExecuteRequest, _auth: bool = Depends(require_ops_auth)):
    intent_id = f"intent_{uuid.uuid4().hex[:12]}"  # type: ignore
    INTENT_STATE[intent_id] = {
        "id": intent_id,
        "status": "running",
        "request": req.model_dump(),
        "started_at": datetime.utcnow().isoformat() + "Z",
    }
    _append_audit({"actor": "openclaw-auto", "type": "intent_start", "intentId": intent_id, "payload": req.model_dump()})

    try:
        result = _run_intent_command(req.commandClass, req.arguments)
        status = "succeeded" if result["exit_code"] == 0 else "failed"
        INTENT_STATE[intent_id].update({"status": status, "result": result, "finished_at": datetime.utcnow().isoformat() + "Z"})
        _append_audit({"actor": "openclaw-auto", "type": "intent_finish", "intentId": intent_id, "status": status, "result": result})
        return {"ok": True, "intentId": intent_id, "status": status, "result": result}
    except Exception as e:
        INTENT_STATE[intent_id].update({"status": "failed", "error": str(e), "finished_at": datetime.utcnow().isoformat() + "Z"})
