                "status": parts[1] if len(parts) > 1 else "unknown",
                "image": parts[2] if len(parts) > 2 else "unknown",
                "running": True,
            }
        )

    return {
        "ok": True,
        "auth": {
            "bearer": bool(AUTH_TOKEN),
            "basic": bool(AUTH_USERNAME and AUTH_PASSWORD),
        },
        "ghas": GHAS_STATE,
        "intents": {
            "active": len([i for i in INTENT_STATE.values() if i.get("status") == "running"]),
