@app.post("/ops/webhook/deploy")
async def ops_webhook_deploy(request: Request, background_tasks: BackgroundTasks):
    raw_body = await request.body()
    signature = request.headers.get("x-deploy-signature", "")
    timestamp = request.headers.get("x-deploy-timestamp", "")
    if not _verify_webhook_signature(signature, timestamp, raw_body):
        raise HTTPException(status_code=401, detail="Invalid webhook signature or timestamp")

    payload = json.loads(raw_body.decode("utf-8"))
    req = DeployWebhookRequest(**payload)
    repo = (
        req.repository
        or ((payload.get("repository") or {}).get("full_name") if isinstance(payload.get("repository"), dict) else None)
        or payload.get("repo")
    )
    ref = req.ref or payload.get("ref")
    sha = req.after or payload.get("after") or payload.get("head_commit", {}).get("id") or "unknown"
    if ref != "refs/heads/main":
        return {"ok": True, "ignored": True, "reason": f"Unsupported ref {ref}; only refs/heads/main is allowed"}

    mapping = _find_repo_mapping(str(repo or ""))
    if not mapping and not req.target and not req.targets:
        raise HTTPException(status_code=400, detail=f"No target mapping found for repo '{repo}'")

    branch = mapping.get("branch", "main") if mapping else "main"
    if ref != f"refs/heads/{branch}":
        return {"ok": True, "ignored": True, "reason": f"Ref {ref} does not match configured branch {branch}"}

    targets: List[str] = []
    if req.target:
        targets.append(req.target)
    targets.extend(req.targets)
    if mapping:
        targets.extend([str(v) for v in mapping.get("targets", []) if v])
    targets = sorted(set(targets))
    if not targets:
        raise HTTPException(status_code=400, detail="No deploy targets resolved from webhook payload")

    results = []
    for target in targets:
        key = _build_idempotency_key(str(repo), str(sha), target)
        existing = WEBHOOK_DELIVERY_STATE.get(key)
        if existing and existing.get("status") == "succeeded":
            results.append({"target": target, "idempotencyKey": key, "status": "skipped", "reason": "already_succeeded"})
            continue

        args = {
            "target": target,
            "imageTag": req.imageTag or req.image,
            "image": req.image,
            "allowInfraDeploy": False,
        }
        result = _run_intent_command("service_deploy", args)
        status = "succeeded" if result["exit_code"] == 0 else "failed"
        WEBHOOK_DELIVERY_STATE[key] = {"status": status, "target": target, "repo": repo, "sha": sha, "updatedAt": datetime.utcnow().isoformat() + "Z"}
        deployment_payload = {
            "ok": result["exit_code"] == 0,
            "target": target,
            "repo": repo,
            "sha": sha,
            "ref": ref,
            "status": status,
            "result": result,
            "idempotencyKey": key,
        }
        target_cfg = _get_deploy_registry().get("targets", {}).get(target, {})
        callback_url = req.callbackUrl or target_cfg.get("callbackUrl") or (mapping.get("callbackUrl") if mapping else "")
        if callback_url:
            background_tasks.add_task(_post_deploy_callback, str(callback_url), deployment_payload, target_cfg)
        _append_audit({"actor": "webhook", "type": "deploy_webhook_target", "payload": deployment_payload})
        results.append(deployment_payload)

    return {"ok": True, "repo": repo, "ref": ref, "sha": sha, "results": results}


async def _run_ghas_harvest(run_id: str, req: GhasHarvestRunRequest):
