    _append_audit({"actor": "system", "type": "ghas_harvest_start", "runId": run_id, "payload": req.model_dump()})
    try:
        cmd = [
            "python3",
            str(GHAS_PIPELINE_SCRIPT),
            "--query-pack",
            req.query_pack,
            "--top-n-per-pack",
            str(req.top_n_per_pack),
            "--limit-per-query",
            str(req.limit_per_query),
