@app.websocket("/ws/logs/{service}")
async def websocket_logs(websocket: WebSocket, service: str):
    """Stream Docker logs via WebSocket."""
    auth_header = websocket.headers.get("authorization", "")
    if not (_valid_bearer(auth_header) or _valid_basic(auth_header)):
        await websocket.close(code=4401, reason="Unauthorized")
        return
    await websocket.accept()
    proc = subprocess.Popen(
        ["docker", "logs", "-f", "--tail", "10", service],
        stdout=subprocess.PIPE,
        text=True
    )
    llm_log("WS_LOG_STREAM_START", {"service": service})
    try:
        while True:
            line = proc.stdout.readline()
            if not line:
                break
            await websocket.send_text(line.strip())
    except Exception as e:
        llm_log("WS_ERROR", {"service": service, "error": str(e)}, "ERROR")
    finally:
        proc.terminate()
        await websocket.close()

