import Cloudflare from "cloudflare";
import { readFileSync } from "node:fs";

// Load secrets directly from ~/.secrets with shell expansion
const secretsContent = readFileSync("/home/toxic/.secrets", "utf-8");
const env: Record<string, string> = {};

for (const line of secretsContent.split("\n")) {
  const trimmed = line.trim();
  if (trimmed.startsWith("export ")) {
    const parts = trimmed.replace("export ", "").split("=");
    if (parts.length >= 2) {
      const k = parts[0].trim();
      const v = parts.slice(1).join("=").trim().replace(/^["']|["']$/g, "");
      env[k] = v;
    }
  }
}

// Expand variables like ${CLOUDFLARE_API_KEY}
for (const [k, v] of Object.entries(env)) {
  if (v.startsWith("${") && v.endsWith("}")) {
    const targetKey = v.slice(2, -1);
    if (env[targetKey]) {
      env[k] = env[targetKey];
    }
  }
}

const apiToken = env.CLOUDFLARE_API_KEY?.startsWith("cfat_") ? env.CLOUDFLARE_API_KEY : env.CF_API_TOKEN;
const email = env.CLOUDFLARE_EMAIL;
const globalKey = env.CLOUDFLARE_GLOBAL_API_KEY;
const accountId = env.CLOUDFLARE_ACCOUNT_ID;

console.log("Using Cloudflare SDK:");
console.log(`- Token type: ${apiToken?.startsWith("cfat_") ? "API Token (cfat_)" : "Other"}`);
console.log(`- Email: ${email ? "SET" : "UNSET"}`);
console.log(`- Account ID: ${accountId}`);

// Initialize client with API Token first
let cf = new Cloudflare({ apiToken });

async function runAudit() {
  try {
    console.log("\n=== 1. ZONES ===");
    const zones = await cf.zones.list();
    console.log(`Total zones found: ${zones.result.length}`);
    for (const z of zones.result) {
      console.log(`\n• Zone: ${z.name} (id: ${z.id}, status: ${z.status})`);

      // List DNS records for this zone
      const records = await cf.dns.records.list({ zone_id: z.id });
      console.log(`  DNS Records (${records.result.length}):`);
      for (const r of records.result) {
        console.log(`    - [${r.type}] ${r.name} -> ${r.content} (proxied: ${r.proxied})`);
      }
    }
  } catch (err: unknown) {
    console.error("Error with API Token:", err);

    // Fallback to Global Key if Token has scope limits
    if (email && globalKey) {
      console.log("\nAttempting fallback with Global API Key...");
      cf = new Cloudflare({ apiEmail: email, apiKey: globalKey });
      try {
        const zones = await cf.zones.list();
        console.log(`Total zones found (Global Key): ${zones.result.length}`);
        for (const z of zones.result) {
          console.log(`• Zone: ${z.name} (id: ${z.id})`);
          const records = await cf.dns.records.list({ zone_id: z.id });
          for (const r of records.result) {
            console.log(`    - [${r.type}] ${r.name} -> ${r.content} (proxied: ${r.proxied})`);
          }
        }
      } catch (fallbackErr: unknown) {
        console.error("Global key error:", fallbackErr);
      }
    }
  }

  // Check Cloudflare Tunnels
  if (accountId) {
    try {
      console.log("\n=== 2. CLOUDFLARE TUNNELS ===");
      const tunnels = await cf.zeroTrust.tunnels.list({ account_id: accountId });
      console.log(`Total tunnels in account: ${tunnels.result.length}`);
      for (const t of tunnels.result) {
        console.log(`• Tunnel: ${t.name} (id: ${t.id}, status: ${t.status})`);

        // Fetch tunnel configuration if available
        try {
          const cfg = await cf.zeroTrust.tunnels.configurations.get(t.id, { account_id: accountId });
          console.log(`  Ingress rules:`, JSON.stringify(cfg.result?.config?.ingress, null, 2));
        } catch (cfgErr: unknown) {
          console.log(`  Could not fetch remote tunnel config: ${cfgErr}`);
        }
      }
    } catch (tErr: unknown) {
      console.error("Tunnel list error:", tErr);
    }
  }
}

runAudit();

