"""
Dedi-Ops Unified Control Client
Direct HTTP/WebSocket client for autonomous agent control of dedicated infrastructure.
"""

from typing import Dict, Any, List, Optional
import httpx
from .config import DediConfig

class DediClient:
    def __init__(self, config: Optional[DediConfig] = None, timeout: float = 30.0):
        self.config = config or DediConfig()
        self.base_url = self.config.api_url.rstrip("/")
        self.timeout = timeout
        self.headers = {"User-Agent": "Sovereign-DediOps/2.0"}
        if self.config.auth_token:
            self.headers["Authorization"] = f"Bearer {self.config.auth_token}"

    def _request(self, method: str, endpoint: str, **kwargs) -> Dict[str, Any]:
        url = f"{self.base_url}/{endpoint.lstrip('/')}"
        with httpx.Client(timeout=self.timeout, verify=False) as client:
            resp = client.request(method, url, headers=self.headers, **kwargs)
            resp.raise_for_status()
            return resp.json()

    # Core Health & Status
    def get_health(self) -> Dict[str, Any]:
        return self._request("GET", "/health")

    def get_dashboard(self) -> Dict[str, Any]:
        """Fetch live system dashboard with active containers, intents, and GHAS status."""
        return self._request("GET", "/ops/dashboard")

    def get_selftest(self) -> Dict[str, Any]:
        return self._request("GET", "/ops/selftest")

    def get_autopsy(self) -> Dict[str, Any]:
        """Fetch remote agent source, environment, and runtime state."""
        return self._request("GET", "/meta/autopsy")

    def get_audit_log(self, limit: int = 50) -> Dict[str, Any]:
        return self._request("GET", f"/ops/audit?limit={limit}")

    # Docker Operations
    def docker_ps(self) -> Dict[str, Any]:
        return self._request("POST", "/docker", json={"action": "ps"})

    def docker_logs(self, service: str, tail: int = 100) -> Dict[str, Any]:
        return self._request("POST", "/docker", json={"action": "logs", "service": service})

    def docker_restart(self, service: str) -> Dict[str, Any]:
        return self._request("POST", "/docker", json={"action": "restart", "service": service})

    # Deploy Targets & Intents
    def get_deploy_targets(self, refresh: bool = False) -> Dict[str, Any]:
        return self._request("GET", f"/ops/deploy/targets?refresh={str(refresh).lower()}")

    def reload_routes(self) -> Dict[str, Any]:
        return self._request("POST", "/ops/routes/reload")

    def execute_intent(self, command_class: str, arguments: Dict[str, Any], target: str = "fleet") -> Dict[str, Any]:
        payload = {
            "intentType": "autonomous_execution",
            "target": target,
            "commandClass": command_class,
            "arguments": arguments,
        }
        return self._request("POST", "/ops/intent/execute", json=payload)

    # Killer Features
    def nuke_port(self, port: int, force: bool = False) -> Dict[str, Any]:
        return self._request("POST", "/sys/nuke_port", json={"port": port, "force": force})

    def list_ghosts(self) -> Dict[str, Any]:
        return self._request("GET", "/temporal/ghosts")

    def create_ghost_snapshot(self, file_path: str = "/app/dedi_agent.py", reason: str = "pre_modification") -> Dict[str, Any]:
        return self._request("POST", "/temporal/snapshot", json={"file_path": file_path, "reason": reason})

    def restore_ghost(self, file_path: str, target_hash: str) -> Dict[str, Any]:
        return self._request("POST", "/temporal/restore", json={"file_path": file_path, "target_hash": target_hash})

from .cli import main

if __name__ == "__main__":
    main()

