def _run_intent_command(command_class: str, args: Dict[str, Any]) -> Dict[str, Any]:
    run_env: Optional[Dict[str, str]] = None
    if command_class == "docker_service_restart":
        svc = args.get("service")
        if not svc:
            raise HTTPException(status_code=400, detail="arguments.service is required")
        cmd = ["docker", "restart", str(svc)]
    elif command_class == "docker_ps":
        cmd = ["docker", "ps", "--format", "json"]
    elif command_class == "logs_capture":
        svc = args.get("service")
        if not svc:
            raise HTTPException(status_code=400, detail="arguments.service is required")
        tail = str(args.get("tail", 200))
        cmd = ["docker", "logs", "--tail", tail, str(svc)]
    elif command_class == "route_reload":
        cmd = ["docker", "restart", "traefik"]
    elif command_class == "health_probe":
        url = args.get("url")
        if not url:
            raise HTTPException(status_code=400, detail="arguments.url is required")
        cmd = ["curl", "-fsS", str(url)]
    elif command_class == "stack_apply":
        services = args.get("services") or []
        run_env = os.environ.copy()
        run_env["COMPOSE_IGNORE_ORPHANS"] = "1"
        if isinstance(services, list) and services:
            cmd = ["docker", "compose", "-f", "docker-compose.modern.yml", "up", "-d", *[str(s) for s in services]]
        else:
            cmd = ["docker", "compose", "-f", "docker-compose.modern.yml", "up", "-d"]
    elif command_class == "tickets_deploy":
        return _run_service_deploy("tickets", args)
    elif command_class == "service_deploy":
        target = str(args.get("target") or "")
        if not target:
            raise HTTPException(status_code=400, detail="arguments.target is required")
        return _run_service_deploy(target, args)
    else:
        raise HTTPException(status_code=400, detail=f"Unsupported commandClass: {command_class}")

    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120, env=run_env)
    result = {
        "command": cmd,
        "exit_code": proc.returncode,
        "stdout": proc.stdout[-12000:],  # type: ignore
        "stderr": proc.stderr[-12000:],  # type: ignore
    }
    return result


